WHERE {
  VALUES ?graph {
    <urn:graphragprov:unit:u_fc1dd1f27dcb3302>
    <urn:graphragprov:unit:u_fcf1976a4c2f8360>
  }
  GRAPH ?graph {
    ?subject ?predicate ?object .
